from haau3 import Haau3

client = Haau3()  # reads HAAU3_API_KEY
parameters = client.code_system_lookup_post(
    {
        "resourceType": "Parameters",
        "parameter": [
            {"name": "system", "valueUri": "http://loinc.org"},
            {"name": "code", "valueCode": "2345-7"},
            {"name": "property", "valueCode": "SHORTNAME"},
        ],
    }
)
for parameter in parameters.get("parameter", []):
    print(parameter.get("name"))

